document.documentElement.classList.add('js');
const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const reveals=document.querySelectorAll('.reveal');
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target);}},{threshold:.08});reveals.forEach(e=>observer.observe(e));}else reveals.forEach(e=>e.classList.add('visible'));
const menu=document.querySelector('.menu-toggle');const nav=document.querySelector('#mobile-nav');
function closeMenu(){nav.hidden=true;menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');document.body.classList.remove('menu-open');}
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='true';if(open)closeMenu();else{nav.hidden=false;menu.setAttribute('aria-expanded','true');menu.setAttribute('aria-label','Close navigation');document.body.classList.add('menu-open');}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!nav.hidden){closeMenu();menu.focus();}});
window.addEventListener('resize',()=>{if(window.innerWidth>900)closeMenu();});
document.querySelector('.back-top').addEventListener('click',()=>window.scrollTo({top:0,behavior:reduced?'instant':'smooth'}));
document.querySelectorAll('a[href]').forEach(a=>a.addEventListener('click',e=>{if(CSS.supports('view-transition-name','root')||reduced||e.defaultPrevented||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||e.button!==0||a.target||a.hasAttribute('download'))return;const url=new URL(a.href);if(url.origin===location.origin&&url.pathname!==location.pathname){e.preventDefault();document.body.classList.add('leaving');setTimeout(()=>location.assign(url.href),150);}}));
window.addEventListener('pageshow',()=>document.body.classList.remove('leaving'));
document.querySelectorAll('.faq-list details').forEach(item=>item.addEventListener('toggle',()=>{if(item.open)item.parentElement.querySelectorAll('details').forEach(other=>{if(other!==item)other.open=false;});}));
const filters=document.querySelectorAll('[data-filter]');filters.forEach(button=>button.addEventListener('click',()=>{filters.forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button));});document.querySelectorAll('[data-category]').forEach(item=>{item.hidden=button.dataset.filter!=='all'&&item.dataset.category!==button.dataset.filter;});}));
const dialog=document.querySelector('#gallery-dialog');if(dialog){let opener;document.querySelectorAll('[data-image]').forEach(button=>button.addEventListener('click',()=>{opener=button;document.querySelector('#gallery-full-image').src='/assets/'+button.dataset.image;document.querySelector('#gallery-full-image').alt=button.dataset.title;document.querySelector('#gallery-dialog-title').textContent=button.dataset.title;dialog.showModal();}));dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});dialog.addEventListener('close',()=>opener?.focus());}
const form=document.querySelector('#enquiry-form');if(form&&!document.querySelector('#challenge-question')){const interest=new URLSearchParams(location.search).get('interest');const select=document.querySelector('#interest');if(interest&&Array.from(select.options).some(o=>o.value===interest))select.value=interest;let enquiry='';form.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(form);enquiry=`Hello Kulture Fitness Club!\nMy name is ${String(data.get('name')).trim()}.\nPhone: ${String(data.get('phone')).trim()}\nI'm interested in: ${data.get('interest')}.`;const message=String(data.get('message')).trim();if(message)enquiry+='\n'+message;document.querySelector('#enquiry-preview').textContent=enquiry;const separator=/iPad|iPhone|iPod/.test(navigator.userAgent)?'&':'?';document.querySelector('#sms-link').href='sms:+919921587777'+separator+'body='+encodeURIComponent(enquiry);const result=document.querySelector('#enquiry-result');result.hidden=false;document.querySelector('#copy-status').textContent='';result.scrollIntoView({behavior:reduced?'instant':'smooth',block:'nearest'});});document.querySelector('#copy-enquiry').addEventListener('click',async()=>{const status=document.querySelector('#copy-status');try{await navigator.clipboard.writeText(enquiry);status.textContent='Enquiry copied. Paste it into your messaging app.';}catch{const selection=window.getSelection();const range=document.createRange();range.selectNodeContents(document.querySelector('#enquiry-preview'));selection.removeAllRanges();selection.addRange(range);status.textContent='Select and copy the enquiry text above.';}});}

